import networkx as nx


def structure_credit(graph, root, total_score, gamma=0.7):
    """按工作流 DAG 的拓扑距离，把单一稀疏总分摊给各角色。"""
    dist = nx.single_source_shortest_path_length(graph, root)
    phi = {v: gamma ** d for v, d in dist.items()}
    z = sum(phi.values())
    return {v: total_score * w / z for v, w in phi.items()}

