import torch.nn.functional as F

def sft_on_corrected(logits, actions, mask):
    # logits: [B, T, A]，actions: [B, T]，mask 标出压缩步与压缩后步
    logp = F.log_softmax(logits, dim=-1)
    tok = logp.gather(-1, actions.unsqueeze(-1)).squeeze(-1)
    return -(tok * mask).sum() / mask.sum().clamp(min=1)

