def cfm_loss(v_net, x1, h, x0=None):
    if x0 is None:
        x0 = torch.randn_like(x1)   # 或由动作历史初始化
    t = torch.rand(x1.shape[0], 1)
    xt = (1 - t) * x0 + t * x1
    return ((v_net(xt, t, h) - (x1 - x0)) ** 2).mean()

import torch

def plan(dyn, z0, z_goal, action_seqs):
    z = z0.expand(len(action_seqs), -1)
    for t in range(action_seqs.shape[1]):
        z = dyn(z, action_seqs[:, t])
    return action_seqs[((z - z_goal) ** 2).sum(-1).argmin()]

