def looped_deep_supervision(loss_fn, outs_per_loop, targets, weights=None):
    # outs_per_loop: 每个循环的输出, len == K
    k = len(outs_per_loop)
    if weights is None:
        weights = [1.0 / k] * k            # 默认等权；原文配比未给出
    total = 0.0
    for w, out in zip(weights, outs_per_loop):
        total = total + w * loss_fn(out, targets)
    return total                            # 循环间深监督：每个循环都拿梯度

